package com.ecommerce.payment; import com.ecommerce.order.*; import com.ecommerce.common.ApiException; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/payments") public class PaymentController {private final PaymentRepository payments;private final OrderRepository orders;public PaymentController(PaymentRepository p,OrderRepository o){payments=p;orders=o;} @PostMapping("/{orderId}/mock-success") @Transactional public Map<String,Object> success(@PathVariable UUID orderId){Payment p=payments.findByOrderId(orderId).orElseThrow(()->new ApiException("Payment not found"));if(p.getStatus()==Payment.Status.SUCCESS)return Map.of("status","SUCCESS","transactionId",p.getTransactionId());p.setStatus(Payment.Status.SUCCESS);p.setTransactionId("MOCK-"+UUID.randomUUID());Order o=orders.findById(orderId).orElseThrow();o.setStatus(Order.Status.PAID);orders.save(o);payments.save(p);return Map.of("status","SUCCESS","transactionId",p.getTransactionId());}}
